select md5(cast(repository as varchar) || '|' || cast(event_id as varchar)) as release_source_key,
       repository, event_id, event_date, kind, title, url, prerelease
from {{ source('raw', 'releases') }}

select md5(cast(repository as varchar) || '|' || cast(endpoint as varchar) || '|' || cast(captured_at as varchar) || '|' || cast(item as varchar)) as discovery_source_key,
       repository, endpoint, captured_at, item, views, uniques, reported_rank
from {{ source('raw', 'discovery') }}

select md5(cast(repository as varchar) || '|' || cast(date as varchar)) as legacy_source_key,
       repository, date, stars, forks
from {{ source('raw', 'legacy') }}

select md5(cast(repository as varchar) || '|' || cast(captured_at as varchar)) as observation_source_key,
       repository, captured_at, stars, forks
from {{ source('raw', 'observations') }}

select md5(cast(repository as varchar) || '|' || cast(endpoint as varchar) || '|' || cast(captured_at as varchar)) as snapshot_source_key,
       repository, endpoint, captured_at, source_file
from {{ source('raw', 'snapshots') }}

select md5(cast(repository as varchar) || '|' || cast(date as varchar)) as traffic_source_key,
       repository, date, clones_total, clones_unique, views_total, views_unique
from {{ source('raw', 'traffic') }}
